package com.pawsshop.model; import javax.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.*;
@Entity public class Sale { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String customerName; private String paymentMethod; private LocalDateTime createdAt; @Column(precision=12,scale=2) private BigDecimal total; @OneToMany(cascade=CascadeType.ALL,fetch=FetchType.EAGER) @JoinColumn(name="sale_id") private List<SaleItem> items=new ArrayList<>();
 public Long getId(){return id;} public String getCustomerName(){return customerName;} public void setCustomerName(String v){customerName=v;} public String getPaymentMethod(){return paymentMethod;} public void setPaymentMethod(String v){paymentMethod=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;} public BigDecimal getTotal(){return total;} public void setTotal(BigDecimal v){total=v;} public List<SaleItem> getItems(){return items;} public void setItems(List<SaleItem> v){items=v;} }
